from fractions import Fraction
def solve(n):
    count = {}
    for d in range(n):
        count[d] = 0
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            count[abs(a - b)] = count[abs(a - b)] + 1
    print(f"two {n}-sided dice, D = |a - b|")
    total = 0
    mean = 0
    for d in count:
        p = Fraction(count[d], n * n)
        print(f"  P(D = {d}) = {count[d]}/{n * n} = {p}")
        total = total + p
        mean = mean + d * p
    print(f"  total: {total}")
    print(f"  E[D] = {mean}")
k = int(input())
for i in range(k):
    solve(int(input()))
